"""Boundary packets H0..H5, P, G (SPLICE-V Fig. 3(a)) with generated byte-exact layouts.

Header: 8 little-endian words (magic, label, version, frame_id, generation,
payload_bytes, count, check).  A packet whose frame_id or generation differs
from the consumer's current frame is a protocol error (roadmap §16): the
consumer stops the frame instead of using stale state.
"""
from __future__ import annotations

from typing import Dict, Tuple

import numpy as np

from . import gen
from .arith import check_word

NP_DTYPE = {"u8": "<u1", "i8": "<i1", "u16": "<u2", "i16": "<i2", "u32": "<u4", "i32": "<i4", "u64": "<u8", "i64": "<i8"}


class StalePacket(Exception):
    pass


def layout(label: str) -> dict:
    return gen.PACKET_LAYOUTS[label]


def pack(label: str, frame_id: int, generation: int, fields: Dict[str, np.ndarray], count: int = 0) -> bytes:
    lay = layout(label)
    payload = bytearray(lay["payload_bytes"])
    for f in lay["fields"]:
        arr = np.asarray(fields.get(f["name"], np.zeros(f["count"])), dtype=np.int64).ravel()
        if arr.size != f["count"]:
            raise ValueError(f"{label}.{f['name']}: {arr.size} elements, layout needs {f['count']}")
        raw = arr.astype(NP_DTYPE[f["dtype"]]).tobytes()
        payload[f["offset"]:f["offset"] + f["bytes"]] = raw
    hdr = [gen.PKT_MAGIC, lay["label_id"], gen.PROTO_VERSION, frame_id & 0xFFFFFFFF, generation & 0xFFFFFFFF,
           lay["payload_bytes"], count & 0xFFFFFFFF, 0]
    words = np.frombuffer(bytes(payload), dtype="<u4")
    hdr[7] = check_word(hdr[:7] + [int(x) for x in words[: min(16, words.size)]])
    return np.asarray(hdr, dtype="<u4").tobytes() + bytes(payload)


def unpack(blob: bytes, expect_label: str, frame_id: int, generation: int) -> Tuple[dict, Dict[str, np.ndarray]]:
    lay = layout(expect_label)
    hdr = np.frombuffer(blob[:32], dtype="<u4").astype(np.int64)
    if hdr[0] != gen.PKT_MAGIC or hdr[1] != lay["label_id"] or hdr[2] != gen.PROTO_VERSION:
        raise ValueError(f"bad packet header for {expect_label}")
    if hdr[3] != (frame_id & 0xFFFFFFFF) or hdr[4] != (generation & 0xFFFFFFFF):
        raise StalePacket(f"{expect_label} belongs to frame {hdr[3]}/{hdr[4]}, expected {frame_id}/{generation}")
    if hdr[5] != lay["payload_bytes"] or len(blob) != 32 + lay["payload_bytes"]:
        raise ValueError(f"{expect_label}: length mismatch")
    payload = blob[32:]
    words = np.frombuffer(payload, dtype="<u4")
    if int(hdr[7]) != check_word([int(x) for x in hdr[:7]] + [int(x) for x in words[: min(16, words.size)]]):
        raise ValueError(f"{expect_label}: check word mismatch")
    out = {}
    for f in lay["fields"]:
        out[f["name"]] = np.frombuffer(payload[f["offset"]:f["offset"] + f["bytes"]], dtype=NP_DTYPE[f["dtype"]]).astype(np.int64)
    meta = {"frame_id": int(hdr[3]), "generation": int(hdr[4]), "count": int(hdr[6])}
    return meta, out


def total_payload_bytes() -> int:
    return sum(l["payload_bytes"] for l in gen.PACKET_LAYOUTS.values())
